const input = $json;
const rawInput = typeof input.input === 'string' ? input.input : (input.message || '');

let name = input.name || input.customer_name || '';
let phone = input.phone || input.customer_phone || '';
let email = input.email || input.customer_email || '';
let issue = input.issue || input.customer_issue || '';
let summary = input.summary || input.conversation_summary || '';

if (rawInput) {
  const nameMatch = rawInput.match(/Name:\s*([^,\n]+)/i);
  const phoneMatch = rawInput.match(/(?:Mobile|Phone)(?:\s*Number)?:\s*([^,\n]+)/i);
  const emailMatch = rawInput.match(/Email:\s*([^,\n]+)/i);
  const issueMatch = rawInput.match(/Issue:\s*([^,\n.]+)/i);
  const summaryMatch = rawInput.match(/Summary:\s*([^\n]+)/i);

  if (!name && nameMatch) name = nameMatch[1].trim();
  if (!phone && phoneMatch) phone = phoneMatch[1].trim();
  if (!email && emailMatch) email = emailMatch[1].trim();
  if (!issue && issueMatch) issue = issueMatch[1].trim();
  if (!summary && summaryMatch) summary = summaryMatch[1].trim();
}

if (!name) name = 'Customer';
if (!issue) issue = 'Requesting to connect with an executive';

const sessionId = input.sessionId || 'session_' + Date.now();
const summaryHtml = summary ? `<p>📄 <b>Summary:</b> ${summary}</p>` : '';

const teamsMessage = `<div>` +
  `<p>🚨 <b>New Customer Escalation — Ascend Pharma Chatbot</b></p>` +
  `<p>👤 <b>Name:</b> ${name}</p>` +
  `<p>📞 <b>Phone:</b> ${phone || 'Not provided'}</p>` +
  `<p>✉️ <b>Email:</b> ${email || 'Not provided'}</p>` +
  `<p>📝 <b>Issue:</b> ${issue}</p>` +
  summaryHtml +
  `<p>⏰ <b>Timestamp:</b> ${new Date().toLocaleString()}</p>` +
`</div>`;

return [{
  json: {
    conversation_id: sessionId,
    session_id: sessionId,
    name,
    phone,
    email,
    issue,
    summary,
    teamsMessage,
    escalated_at: new Date().toISOString()
  }
}];
